		// Split 7-7 against dealer 2-7; Hit against 8-A
		if dealerValue >= 2 && dealerValue <= 7 {
			return SplitAction
		} else {
			return HitAction
		}
	case cards.Six:
		// Split 6-6 against dealer 2-6; Hit against 7-A
		if dealerValue >= 2 && dealerValue <= 6 {
			return SplitAction
		} else {
			return HitAction
		}
	case cards.Five:
		// Treat as hard 10
		return sa.getHardHandStrategy(10, dealerValue)
	case cards.Four:
		// Split 4-4 against dealer 5-6 only (if DAS allowed)
		if sa.RuleSet.DoubleAfterSplit && dealerValue == 5 || dealerValue == 6 {
			return SplitAction
		} else {
			return HitAction
		}
	case cards.Three, cards.Two:
		// Split 2-2, 3-3 against dealer 2-7; Hit against 8-A
		if dealerValue >= 2 && dealerValue <= 7 {
			return SplitAction
		} else {
			return HitAction
		}
	}

	// Default: don't split
	return ""
}

// getSoftHandStrategy returns the recommended action for a soft hand
func (sa *StrategyAdvisor) getSoftHandStrategy(playerSum int, dealerValue int) Action {
	// Basic soft hand strategy
	switch playerSum {
	case 20: // A-9
		return StandAction
	case 19: // A-8
		// Stand, except double against dealer 6 (if allowed and only first 2 cards)
		if dealerValue == 6 {
			return DoubleAction
		}
		return StandAction
	case 18: // A-7
		if dealerValue == 2 || dealerValue == 7 || dealerValue == 8 {
			return StandAction
		} else if dealerValue >= 3 && dealerValue <= 6 {
			// Double if allowed, otherwise stand
			return DoubleAction
