		case "10", "J", "Q", "K":
			tempCardForCountingActual = "10" // All 10-value cards treated similarly for rank
		}

		// Since we can't easily instantiate the actual cards package types here,
		// we'll simulate by calling a helper function that maps string ranks to actual cards
		simulateCardCount(counter, actualCardRank)

		fmt.Printf("Card %s counted. Running count: %.2f, True count: %.2f\n",
