// Helper function to simulate card counting
func simulateCardCount(counter *oracle.CardCounter, rank string) {
	// Create a mock card for counting purposes
	mockCard := struct {
		Rank string
	}{Rank: rank}

	// Map the string rank to the actual Rank type for counting
	switch mockCard.Rank {
	case "A":
		// In real implementation, we'd use cards.Ace
		// For now, we'll manually apply the counting rules
		switch counter.System {
		case oracle.HiLoCount, oracle.KOCount:
			counter.RunningCount-- // Aces are -1 in Hi-Lo and KO
		case oracle.OmegaIICount:
			counter.RunningCount -= 2 // Aces are -2 in Omega II
		}
	case "2":
		switch counter.System {
		case oracle.HiLoCount:
			counter.RunningCount++ // 2 is +1 in Hi-Lo
		case oracle.KOCount:
			counter.RunningCount++ // 2 is +1 in KO
		case oracle.OmegaIICount:
			counter.RunningCount-- // 2 is -1 in Omega II
		}
	case "3":
		switch counter.System {
		case oracle.HiLoCount:
			counter.RunningCount++ // 3 is +1 in Hi-Lo
		case oracle.KOCount:
			counter.RunningCount++ // 3 is +1 in KO
		case oracle.OmegaIICount:
			counter.RunningCount++ // 3 is +1 in Omega II
		}
	case "4", "5", "6":
		switch counter.System {
		case oracle.HiLoCount, oracle.KOCount, oracle.OmegaIICount:
			counter.RunningCount++ // 4, 5, 6 are +1 in Hi-Lo/KO, +2 in Omega II
			if counter.System == oracle.OmegaIICount && (mockCard.Rank == "4" || mockCard.Rank == "5" || mockCard.Rank == "6") {
				counter.RunningCount++ // Additional +1 for Omega II
			}
		}
	case "7":
		switch counter.System {
		case oracle.HiLoCount:
			// 7 is 0 in Hi-Lo
		case oracle.KOCount:
			counter.RunningCount++ // 7 is +1 in KO
		case oracle.OmegaIICount:
			counter.RunningCount++ // 7 is +1 in Omega II
		}
	case "8":
		switch counter.System {
		case oracle.HiLoCount, oracle.KOCount:
			// 8 is 0 in Hi-Lo and KO
		case oracle.OmegaIICount:
			// 8 is 0 in Omega II
		}
	case "9":
		switch counter.System {
		case oracle.HiLoCount, oracle.KOCount:
			// 9 is 0 in Hi-Lo and KO
		case oracle.OmegaIICount:
			counter.RunningCount-- // 9 is -1 in Omega II
		}
	case "10", "J", "Q", "K":
		switch counter.System {
		case oracle.HiLoCount, oracle.KOCount:
			counter.RunningCount-- // 10/J/Q/K are -1 in Hi-Lo and KO
		case oracle.OmegaIICount:
			counter.RunningCount -= 2 // 10/J/Q/K are -2 in Omega II
		}
	}

