+	engine.State = PlayerTurnState
+	
+	initialChips := player.Chips
+	err := engine.Split(1)
+	if err != nil {
+		t.Fatalf("Unexpected error splitting: %v", err)
+	}
+	
+	if len(player.Hands) != 2 {
+		t.Fatalf("Expected 2 hands after split, got %d", len(player.Hands))
