+func TestCalculateHandResult(t *testing.T) {
+	engine := NewGameEngine(&RuleSet{BlackjackPayout: 1.5})
+	
+	// Player wins
+	playerHand := &Hand{Cards: []cards.Card{{Rank: cards.Ten}, {Rank: cards.Nine}}, IsBusted: false}
+	dealerHand := &Hand{Cards: []cards.Card{{Rank: cards.Eight}, {Rank: cards.Seven}}, IsBusted: false}
+	engine.Dealer = dealerHand
