+package simulation
+
+import (
+	"testing"
+	"time"
+
+	"blackjack/internal/game"
+	"blackjack/pkg/cards"
+)
+
+func TestNewSimulator(t *testing.T) {
+	rules := &game.RuleSet{}
+	strategy := &BasicStrategy{}
+
+	simulator := NewSimulator(1000, rules, strategy)
+
+	if simulator.Runs != 1000 {
+		t.Errorf("Expected runs to be 1000, got %d", simulator.Runs)
+	}
+
+	if simulator.Rules != rules {
+		t.Errorf("Expected rules to match, but they don't")
+	}
+
+	if simulator.Strategy != strategy {
+		t.Errorf("Expected strategy to match, but they don't")
+	}
+
+	if simulator.StartingChips != 1000.0 {
+		t.Errorf("Expected starting chips to be 1000.0, got %f", simulator.StartingChips)
+	}
+}
+
+func TestSimulatorRun(t *testing.T) {
+	rules := &game.RuleSet{
+		NumDecks:          6,
+		DealerHitsSoft17:  true,
+		DoubleAfterSplit:  true,
+		SplitAcesOnceOnly: true,
+		LateSurrender:     true,
+		InsuranceAllowed:  true,
+		BlackjackPayout:   1.5,
+	}
+	strategy := &BasicStrategy{}
+
+	simulator := NewSimulator(100, rules, strategy) // Small number for quick test
+
+	result := simulator.Run()
+
+	if result.TotalHands != 100 {
+		t.Errorf("Expected total hands to be 100, got %d", result.TotalHands)
+	}
+
+	// Verify that all the statistics are calculated
+	if result.WinRate < 0 || result.WinRate > 1 {
+		t.Errorf("Win rate should be between 0 and 1, got %f", result.WinRate)
+	}
+
+	if result.ExpectedValue == 0 && result.TotalHands > 0 {
+		t.Errorf("Expected non-zero expected value for realistic simulation, got %f", result.ExpectedValue)
+	}
+
+	if result.HouseEdge == 0 && result.TotalHands > 0 {
+		t.Errorf("Expected non-zero house edge for realistic simulation, got %f", result.HouseEdge)
+	}
+}
+
+func TestRunWorker(t *testing.T) {
+	rules := &game.RuleSet{
+		NumDecks:          6,
+		DealerHitsSoft17:  true,
+		DoubleAfterSplit:  true,
+		SplitAcesOnceOnly: true,
+		LateSurrender:     true,
+		InsuranceAllowed:  true,
+		BlackjackPayout:   1.5,
+	}
+	strategy := &BasicStrategy{}
+
+	simulator := NewSimulator(50, rules, strategy)
+
+	result := simulator.runWorker(50)
+
+	if result.TotalHands != 50 {
+		t.Errorf("Expected total hands to be 50, got %d", result.TotalHands)
+	}
+
+	// The sum of all outcome types should equal total hands
+	totalOutcomes := result.PlayerWins + result.DealerWins + result.Pushes
+	if totalOutcomes != result.TotalHands {
+		t.Errorf("Expected outcome sum (%d) to equal total hands (%d)", totalOutcomes, result.TotalHands)
+	}
+}
+
+func TestPlayHand(t *testing.T) {
+	rules := &game.RuleSet{
+		NumDecks:          1,
+		DealerHitsSoft17:  true,
+		DoubleAfterSplit:  true,
+		SplitAcesOnceOnly: true,
+		LateSurrender:     true,
+		InsuranceAllowed:  true,
+		BlackjackPayout:   1.5,
+	}
+	strategy := &BasicStrategy{}
+
+	simulator := NewSimulator(1, rules, strategy)
+
+	// Create a simple deck for predictable testing
+	shoe := cards.NewShoe(1)
+	shoe.Shuffle() // Just shuffle the deck
+
+	// Create a player with known cards for testing
+	player := &game.Player{
+		ID:    1,
+		Name:  "Test Player",
+		Chips: 1000.0,
+		Hands: []*game.Hand{},
+		CurrentBet: 10.0,
+	}
+
+	// Create a hand for the player
+	player.Hands = append(player.Hands, &game.Hand{
+		Cards: []cards.Card{
+			{Rank: cards.Ten, Suit: cards.Spades, Value: 10},
+			{Rank: cards.Nine, Suit: cards.Hearts, Value: 9}, // Total 19
+		},
+		Bet:    10.0,
+		Active: true,
+	})
+
+	// Create a dealer with known cards
+	dealer := &game.Hand{
+		Cards: []cards.Card{
+			{Rank: cards.Six, Suit: cards.Spades, Value: 6},
+			{Rank: cards.Five, Suit: cards.Hearts, Value: 5}, // Total 11
+		},
+	}
+
+	// Play the hand
+	result := simulator.playHand(shoe, player, dealer, strategy)
+
+	// The player has 19, dealer has 11 - expect player to win
+	if result == nil {
+		t.Fatal("Expected result to not be nil")
+	}
+}
+
+func TestPlayHandWithBlackjack(t *testing.T) {
+	rules := &game.RuleSet{
+		NumDecks:          1,
+		DealerHitsSoft17:  true,
+		DoubleAfterSplit:  true,
+		SplitAcesOnceOnly: true,
+		LateSurrender:     true,
+		InsuranceAllowed:  true,
+		BlackjackPayout:   1.5,
+	}
+	strategy := &BasicStrategy{}
+
+	simulator := NewSimulator(1, rules, strategy)
+
+	// Create a simple deck for predictable testing
+	shoe := cards.NewShoe(1)
+	shoe.Shuffle() // Just shuffle the deck
+
+	// Create a player with blackjack
+	player := &game.Player{
+		ID:    1,
+		Name:  "Test Player",
+		Chips: 1000.0,
+		Hands: []*game.Hand{},
+		CurrentBet: 10.0,
+	}
+
+	// Create a blackjack hand for the player
+	player.Hands = append(player.Hands, &game.Hand{
+		Cards: []cards.Card{
+			{Rank: cards.Ace, Suit: cards.Spades, Value: 1},
+			{Rank: cards.King, Suit: cards.Hearts, Value: 10}, // Blackjack
+		},
+		Bet:         10.0,
+		Active:      true,
+		IsBlackjack: true,
+	})
+
+	// Create a dealer with non-blackjack
+	dealer := &game.Hand{
+		Cards: []cards.Card{
+			{Rank: cards.Six, Suit: cards.Spades, Value: 6},
+			{Rank: cards.Five, Suit: cards.Hearts, Value: 5}, // Total 11
+		},
+	}
+
+	// Play the hand
+	result := simulator.playHand(shoe, player, dealer, strategy)
+
+	// The player has blackjack - expect appropriate result
+	if result == nil {
+		t.Fatal("Expected result to not be nil")
+	}
+}
+
+func TestSimulationResultCalculations(t *testing.T) {
+	result := &SimulationResult{
+		TotalHands:        100,
+		PlayerWins:        40,
+		DealerWins:        50,
+		Pushes:            10,
+		PlayerBlackjacks:  5,
+		NetProfit:         -10.0,
+		AvgBetSize:        10.0,
+	}
+
+	// Calculate derived statistics
+	winRate := float64(result.PlayerWins) / float64(result.TotalHands)
+	expectedValue := result.NetProfit / float64(result.TotalHands)
+	houseEdge := -expectedValue / result.AvgBetSize
+
+	if winRate != 0.4 {
+		t.Errorf("Expected win rate to be 0.4, got %f", winRate)
+	}
+
+	if expectedValue != -0.1 {
+		t.Errorf("Expected expected value to be -0.1, got %f", expectedValue)
+	}
+
+	if houseEdge != 0.01 {
+		t.Errorf("Expected house edge to be 0.01, got %f", houseEdge)
+	}
+}
+
+func TestSimulatorPerformance(t *testing.T) {
+	rules := &game.RuleSet{}
+	strategy := &BasicStrategy{}
+
+	simulator := NewSimulator(1000, rules, strategy)
+
+	start := time.Now()
+	result := simulator.Run()
+	duration := time.Since(start)
+
+	if duration > 10*time.Second {
+		t.Errorf("Simulation took too long: %v", duration)
+	}
+
+	if result.TotalHands != 1000 {
+		t.Errorf("Expected 1000 hands, got %d", result.TotalHands)
+	}
+}

