		}
		return oracle.HitAction
	case 12:
		if dealerValue >= 4 && dealerValue <= 6 {
			return oracle.StandAction
		}
		return oracle.HitAction
	case 11:
		return oracle.DoubleAction
	case 10:
		if dealerValue >= 2 && dealerValue <= 9 {
