// runWorker performs a portion of the total simulation runs.
//
// The shoe is held across hands rather than recreated per hand. That is
// required for card counting to mean anything: a per-hand shoe resets the
// count to zero before every decision and never advances penetration.
func (s *Simulator) runWorker(workerID, runs int) *SimulationResult {
	result := &SimulationResult{}

	// Per-worker RNG. The previous global rand.Seed call raced across the four
	// goroutines and defeated reproducibility.
	rng := rand.New(rand.NewSource(s.Seed + int64(workerID)))

	numDecks := s.RuleSet.NumDecks
	if numDecks <= 0 {
		numDecks = 6
	}
	totalCards := numDecks * 52
	reshuffleAt := (totalCards * 75) / 100 // reshuffle once 75% penetration is reached

	shoe := cards.NewShoe(numDecks)
	shoe.Shuffle()
	counter := oracle.NewCardCounter(s.CountSystem, numDecks)
	cardsDealt := 0

	for i := 0; i < runs; i++ {
		if cardsDealt >= reshuffleAt {
			shoe = cards.NewShoe(numDecks)
			shoe.Shuffle()
			counter.Reset(numDecks)
			cardsDealt = 0
		}

		outcome, dealt := s.simulateSingleGame(shoe, counter, rng)
		cardsDealt += dealt
		counter.UpdateDecksPlayed(cardsDealt)
		s.updateResult(result, outcome)
	}

	return result
}
