// SimulationResult holds the results of a simulation run
type SimulationResult struct {
	TotalHands       int
	PlayerWins       int
	DealerWins       int
	Pushes           int
	PlayerBlackjacks int
	NetProfit        float64
	ExpectedValue    float64
